(() => {
    const scroller = document.querySelector('#editor .cm-scroller');
    const scrollTop = scroller?.scrollTop;
    if (Number.isFinite(scrollTop)) {
        window.__mimoExecutableLessonInstructionsEditorScrollTop = scrollTop;
    } else {
        delete window.__mimoExecutableLessonInstructionsEditorScrollTop;
    }
    Spieglein.dispatchMessage({"type":"remove editor focus"});
})()

(() => {
    const scroller = document.querySelector('#editor .cm-scroller');
    const scrollTop = window.__mimoExecutableLessonInstructionsEditorScrollTop;
    if (scroller && Number.isFinite(scrollTop)) {
        scroller.scrollTop = scrollTop;
    }
    delete window.__mimoExecutableLessonInstructionsEditorScrollTop;
})()

(() => {
    const id = 'mimo-android-completion-badge-style';
    if (document.getElementById(id)) return;
    const style = document.createElement('style');
    style.id = id;
    style.textContent = `
        .cm-completionIcon-text { flex-shrink: 0; }
        .cm-completionIcon-text::after {
            display: inline-block;
            transform: scale(0.5);
            transform-origin: left center;
        }
    `;
    document.head.appendChild(style);
})()
